const LINES = {};
LINES_DATA.forEach(l => { LINES[String(l.final)] = l; });
function getLine(final) { return LINES[String(final)] || null; }

// Which form a Pokémon on this line is at a given level.
// A step with no evolution level is treated as already passed (it simply is that Pokémon).
function formAtLevel(final, level) {
  const line = getLine(final); if (!line) return null;
  let i = 0;
  while (i < line.path.length - 1) {
    const lv = line.path[i].level;
    if (lv === null || level >= lv) i++; else break;
  }
  return line.path[i].name;
}
// Next evolution for a player's Pokémon: { into, level } or null. Steps without a level don't happen by leveling.
function nextEvolution(final, currentName) {
  const line = getLine(final); if (!line) return null;
  const i = line.path.findIndex(s => s.name === currentName);
  if (i < 0 || i >= line.path.length - 1 || line.path[i].level === null) return null;
  return { into: line.path[i + 1].name, level: line.path[i].level };
}
